"""Deterministic pre-render QA for Paperclip meta-analysis artifacts."""

from __future__ import annotations

import argparse
import hashlib
import json
from pathlib import Path
from typing import Any

from .analysis_contracts import validate_analysis


def load_json(path: Path) -> Any:
    if not path.exists():
        raise ValueError(f"missing required artifact: {path.name}")
    return json.loads(path.read_text())


def load_json_optional(path: Path) -> Any | None:
    if not path.exists():
        return None
    return json.loads(path.read_text())


def _sha256_path(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def run_checks(directory: Path, schema_path: Path | None = None) -> dict[str, Any]:
    """Validate guided-project artifacts using dynamic contracts."""
    from gxl_paperclip.analysis_project.contracts import (
        collection_schema_hash,
        validate_collection_spec,
        validate_evidence_proposal,
        validate_extraction_audit,
        validate_harmonization_map,
        validate_harmonization_pilot_coherence,
        validate_planned_outputs,
        validate_protocol,
        validate_search_log,
        validate_synthesis,
    )

    criticals: list[str] = []
    warnings: list[str] = []

    try:
        verified = load_json(directory / "verified_findings.json")
        analysis = load_json(directory / "analysis.json")
        search_log = load_json(directory / "search_log.json")
        audit = load_json(directory / "extraction_audit.json")
        protocol = load_json(directory / "protocol.json")
        synthesis = load_json(directory / "synthesis.json")
        prisma = load_json(directory / "prisma_checklist.json")
        collection_spec = load_json(directory / "collection_spec.json")
        planned_outputs = load_json(directory / "planned_outputs.json")
        evidence_proposal = load_json(directory / "evidence_proposal.json")
        harmonization_map = load_json(directory / "harmonization_map.json")
    except (ValueError, json.JSONDecodeError) as exc:
        criticals = [str(exc)]
        return {
            "status": "fail",
            "critical": criticals,
            "criticals": criticals,
            "warnings": [],
        }

    # --- Dynamic contract validation ---

    for name, validator, args in (
        ("collection_spec.json", validate_collection_spec, (collection_spec,)),
        ("planned_outputs.json", validate_planned_outputs, (planned_outputs,)),
        (
            "evidence_proposal.json",
            validate_evidence_proposal,
            (evidence_proposal, verified),
        ),
        ("search_log.json", validate_search_log, (search_log,)),
        ("extraction_audit.json", validate_extraction_audit, (audit,)),
        ("protocol.json", validate_protocol, (protocol,)),
        ("synthesis.json", validate_synthesis, (synthesis,)),
    ):
        result = validator(*args)
        criticals.extend(f"{name}: {error}" for error in result.errors)
        warnings.extend(f"{name}: {warning}" for warning in result.warnings)

    findings_sha = _sha256_path(directory / "verified_findings.json")
    proposal_sha = _sha256_path(directory / "evidence_proposal.json")
    coll_hash = (
        collection_schema_hash(collection_spec) if isinstance(collection_spec, dict) else None
    )
    harmonization_queue = load_json_optional(directory / "harmonization_queue.json")
    queue_sha = (
        _sha256_path(directory / "harmonization_queue.json")
        if harmonization_queue is not None
        else None
    )
    hm_result = validate_harmonization_map(
        harmonization_map,
        collection_hash=coll_hash,
        verified_findings_sha256=findings_sha,
        evidence_proposal_sha256=proposal_sha,
        harmonization_queue=harmonization_queue,
        harmonization_queue_sha256=queue_sha,
        final=True,
    )
    criticals.extend(f"harmonization_map.json: {error}" for error in hm_result.errors)
    warnings.extend(f"harmonization_map.json: {warning}" for warning in hm_result.warnings)
    coherence = validate_harmonization_pilot_coherence(
        collection_spec,
        harmonization_map,
    )
    criticals.extend(
        f"harmonization_map.json: {error}" for error in coherence.errors
    )
    warnings.extend(
        f"harmonization_map.json: {warning}" for warning in coherence.warnings
    )

    # --- Verified findings provenance ---

    if not isinstance(verified, dict) or not isinstance(verified.get("findings"), list):
        criticals.append("verified_findings.json must have a findings array")
    else:
        generator = verified.get("generator")
        if generator != "gxl_paperclip.meta_analysis.export_verified":
            criticals.append(
                f"verified_findings.json generator is {generator!r}, expected "
                "'gxl_paperclip.meta_analysis.export_verified'"
            )
        if not verified["findings"]:
            criticals.append("verified_findings.json has zero findings")

    findings_count = len(verified.get("findings", [])) if isinstance(verified, dict) else 0

    # --- Analysis contract ---

    if not isinstance(analysis, dict):
        criticals.append("analysis.json must be an object")
    else:
        contract = validate_analysis(analysis, None)
        criticals.extend(f"analysis contract: {error}" for error in contract.errors)

    # --- PRISMA ---

    if not isinstance(prisma, dict) or not prisma:
        criticals.append("prisma_checklist.json is empty or malformed")
    else:
        prisma_items = prisma.get("items")
        if not isinstance(prisma_items, list) or len(prisma_items) < 27:
            criticals.append("PRISMA checklist does not contain all 27 items")
        elif any(
            not isinstance(item, dict)
            or item.get("status") not in {"addressed", "not_applicable"}
            or (item.get("status") == "not_applicable" and not item.get("note"))
            for item in prisma_items
        ):
            criticals.append("PRISMA checklist has missing/invalid item statuses")

    # --- Managed execution binding ---

    result_obj: dict[str, Any] = {
        "status": "fail" if criticals else "pass",
        "critical": criticals,
        "criticals": criticals,
        "warnings": warnings,
        "counts": {
            "verified_findings": findings_count,
        },
    }
    state_path = directory / "analysis_project.json"
    if state_path.is_file() and (
        (directory / "analysis").is_dir() or (directory / "analysis.json").is_file()
    ):
        try:
            from gxl_paperclip.analysis_project import (
                AnalysisProjectStore,
                validate_current_execution,
            )

            execution = validate_current_execution(AnalysisProjectStore().load(directory))
        except Exception as exc:  # noqa: BLE001
            result_obj["criticals"].append(f"managed analysis execution: {exc}")
        else:
            result_obj["analysis_execution_sha256"] = execution["execution_sha256"]
            result_obj["analysis_sha256"] = execution["analysis_sha256"]
            result_obj["criticals"].extend(
                f"managed analysis execution: {error}" for error in execution["errors"]
            )
        result_obj["status"] = "fail" if result_obj["criticals"] else "pass"
    return result_obj


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("directory", nargs="?", default=".")
    args = parser.parse_args(argv)
    directory = Path(args.directory)
    result = run_checks(directory)
    (directory / "data_qa.json").write_text(json.dumps(result, indent=2) + "\n")
    print(json.dumps(result, indent=2))
    return 0 if result["status"] == "pass" else 1


if __name__ == "__main__":
    raise SystemExit(main())
